var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// Build the ChatClientAgent with tools and instructions
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the take_note tool to record key findings as you go.
        3. Use the get_notes tool to review all collected notes.
        4. Provide a comprehensive summary of your research findings.
        Be thorough — search for multiple aspects of the topic.
        """,
    name: "ResearchAgent",
    tools:
    [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

// Wrap in a LoopAgent to cap iterations and enable tool-call loops
var loopAgent = new LoopAgent(agent, options: new LoopAgentOptions { MaxIterations = 10 });

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    var runOptions = new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    });

    Console.WriteLine("\nResearching...\n");

    await foreach (var update in loopAgent.RunStreamingAsync(
        $"Research the following topic and provide a summary: {input}",
        session: null,
        runOptions))
    {
        if (!string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine("\n");
    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a given query. Returns search result snippets.")]
    public string WebSearch([Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing, Google, Brave) in production.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return $$"""
            Search results for "{{query}}":
            1. {{query}} - Overview from Wikipedia: This topic covers key aspects including history, 
               current developments, and future outlook. Multiple sources confirm its significance 
               in the relevant field.
            2. Recent News: Latest developments in {{query}} show growing interest and new research 
               findings published in 2026.
            3. Expert Analysis: Domain experts highlight that {{query}} has important implications 
               for technology and society, with several ongoing studies.
            """;
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to record")] string note,
        [Description("Optional source or category for the note")] string? source = null)
    {
        var entry = source is not null ? $"[{source}] {note}" : note;
        _notes.Add(entry);
        Console.WriteLine($"  [Tool] Note taken: {entry[..Math.Min(entry.Length, 80)]}...");
        return $"Note recorded successfully. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

